#include "game/modern_world_updates_internal.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <tig/tig.h>

#define STATE_LIMIT (64u*1024u*1024u)
#define STATE_ENTRIES 131072u
typedef struct StateOp {char id[RW_ID_SIZE];uint8_t digest[32];uint32_t outcome;} StateOp;
typedef struct StatePackage {char id[RW_ID_SIZE],module[RW_ID_SIZE];uint32_t revision,previous_revision,op_count,resource_count;uint8_t digest[32],previous_digest[32];StateOp* ops;RwResource* resources;} StatePackage;
typedef struct StateRoof {char map[RW_ID_SIZE];uint64_t sector;uint32_t index,value;} StateRoof;
static StatePackage state_packages[RW_MAX_PACKAGES];
static unsigned state_count,roof_count;
static StateRoof* state_roofs;
static char state_directory[RW_PATH_SIZE],state_slot[65],backup_directory[RW_PATH_SIZE];
static bool backed_up;
static unsigned serial;

static bool fail(const char* text){rw_error("%s",text);return false;}
static bool component(const char* s){if(!s || !*s || !strcmp(s,".") || !strcmp(s,"..") || strlen(s)>63)return false;for(;*s;s++)if(!((*s>='a'&&*s<='z')||(*s>='A'&&*s<='Z')||(*s>='0'&&*s<='9')||*s=='_'||*s=='-'||*s=='.'))return false;return true;}
static bool path_join(char out[RW_PATH_SIZE],const char* root,const char* tail){if(snprintf(out,RW_PATH_SIZE,"%s/%s",root,tail)>=RW_PATH_SIZE)return fail("World update path exceeds native path limit");return true;}
static bool module_path(char out[RW_PATH_SIZE],const char* tail){if(!*state_directory)return fail("World update module directory is not bound");return path_join(out,state_directory,tail);}
static bool exists(const char* path){return tig_file_exists(path,NULL);}
static bool mkdirs(const char* path){char copy[RW_PATH_SIZE];if(strlen(path)>=sizeof(copy))return false;strcpy(copy,path);for(char* p=copy+1;*p;p++)if(*p=='/'||*p=='\\'){char c=*p;*p=0;if(copy[strlen(copy)-1]!=':' && !tig_file_is_directory(copy) && !tig_file_mkdir(copy))return false;*p=c;}return tig_file_is_directory(copy)||tig_file_mkdir(copy);}
static bool physical(char out[RW_PATH_SIZE],const char* in){int n=snprintf(out,RW_PATH_SIZE,"%s%s",in[0]=='.'||in[0]=='/'||in[0]=='\\'||(strlen(in)>1&&in[1]==':')?"":"./",in);return n>0&&n<RW_PATH_SIZE;}
static bool copy(const char* dst,const char* src){char a[RW_PATH_SIZE],b[RW_PATH_SIZE];if(!physical(a,dst)||!physical(b,src))return false;TigFile* in=tig_file_fopen(b,"rb");if(!in)return false;TigFile* out=tig_file_fopen(a,"wb");if(!out){tig_file_fclose(in);return false;}long size=tig_file_filelength(in);bool ok=size>=0;unsigned char buffer[32768];while(ok&&size>0){size_t n=size>(long)sizeof(buffer)?sizeof(buffer):(size_t)size;ok=tig_file_fread(buffer,1,n,in)==n&&tig_file_fwrite(buffer,1,n,out)==n;size-=(long)n;}if(tig_file_fclose(out)!=0)ok=false;if(tig_file_fclose(in)!=0)ok=false;return ok;}
void rw_state_set_directory(const char* directory){if(!directory || !physical(state_directory,directory)){state_directory[0]=0;rw_error("Invalid module directory for world updates");}}
void rw_state_reset(void){for(unsigned i=0;i<state_count;i++){free(state_packages[i].ops);free(state_packages[i].resources);}memset(state_packages,0,sizeof(state_packages));state_count=roof_count=0;free(state_roofs);state_roofs=NULL;state_slot[0]=backup_directory[0]=0;backed_up=false;}

typedef struct Codec {TigFile* file;size_t bytes;bool ok;} Codec;
static void io(Codec* c,void* bytes,size_t n,bool write){if(!c->ok)return;if(n>STATE_LIMIT-c->bytes){c->ok=false;return;}c->bytes+=n;if((write?tig_file_fwrite(bytes,1,n,c->file):tig_file_fread(bytes,1,n,c->file))!=n)c->ok=false;}
static uint32_t u32(Codec* c,uint32_t value,bool write){uint8_t b[4];for(unsigned i=0;i<4;i++)b[i]=(uint8_t)(value>>(8*i));io(c,b,4,write);value=0;for(unsigned i=0;i<4;i++)value|=(uint32_t)b[i]<<(8*i);return value;}
static uint64_t u64(Codec* c,uint64_t v,bool write){uint64_t lo=u32(c,(uint32_t)v,write),hi=u32(c,(uint32_t)(v>>32),write);return lo|(hi<<32);}
static void text(Codec* c,char* s,size_t capacity,bool write){uint32_t n=u32(c,write?(uint32_t)strlen(s):0,write);if(n>=capacity){c->ok=false;return;}io(c,s,n,write);if(!write){s[n]=0;if(memchr(s,0,n))c->ok=false;}}
static bool checksum(TigFile* file,bool append){size_t n=tig_file_filelength(file);if(n>STATE_LIMIT||(!append&&n<32))return false;size_t payload=append?n:n-32;uint8_t* bytes=malloc(payload?payload:1);uint8_t digest[32],stored[32];if(!bytes)return false;bool ok=tig_file_fseek(file,0,SEEK_SET)==0&&tig_file_fread(bytes,1,payload,file)==payload;if(ok){rw_sha256(bytes,payload,digest);if(append)ok=tig_file_fseek(file,(long)payload,SEEK_SET)==0&&tig_file_fwrite(digest,1,32,file)==32;else ok=tig_file_fread(stored,1,32,file)==32&&!memcmp(digest,stored,32);}free(bytes);return ok;}
static int roof_compare(const void* left,const void* right){const StateRoof* a=left;const StateRoof* b=right;int map=strcmp(a->map,b->map);if(map)return map;if(a->sector!=b->sector)return a->sector<b->sector?-1:1;return a->index<b->index?-1:a->index>b->index?1:0;}
static bool state_codec(Codec* c,bool write){char magic[8]={'R','W','S','A','V','0','1',0};char expected[8];memcpy(expected,magic,8);io(c,magic,8,write);if(memcmp(magic,expected,8)||u32(c,1,write)!=1)return false;
    uint32_t count=u32(c,state_count,write);if(count>RW_MAX_PACKAGES)return false;if(!write)state_count=count;
    for(unsigned i=0;i<count&&c->ok;i++){StatePackage* p=&state_packages[i];text(c,p->id,sizeof(p->id),write);text(c,p->module,sizeof(p->module),write);p->revision=u32(c,p->revision,write);io(c,p->digest,32,write);p->op_count=u32(c,p->op_count,write);p->resource_count=u32(c,p->resource_count,write);if(!component(p->id)||!component(p->module)||!p->revision||p->op_count>RW_MAX_OPERATIONS||p->resource_count>RW_MAX_RESOURCES)return false;
        if(!write){p->ops=calloc(p->op_count?p->op_count:1,sizeof(*p->ops));p->resources=calloc(p->resource_count?p->resource_count:1,sizeof(*p->resources));if(!p->ops||!p->resources)return false;}
        for(unsigned j=0;j<p->op_count&&c->ok;j++){StateOp* o=&p->ops[j];text(c,o->id,sizeof(o->id),write);io(c,o->digest,32,write);o->outcome=u32(c,o->outcome,write);if(!component(o->id)||o->outcome>RW_FAILED)return false;for(unsigned k=0;k<j;k++)if(!strcmp(o->id,p->ops[k].id))return false;}
        for(unsigned j=0;j<p->resource_count&&c->ok;j++){text(c,p->resources[j].path,RW_PATH_SIZE,write);io(c,p->resources[j].digest,32,write);for(unsigned k=0;k<j;k++)if(!strcmp(p->resources[j].path,p->resources[k].path))return false;}
        for(unsigned j=0;j<i;j++)if(!strcmp(p->id,state_packages[j].id))return false;
    }
    uint32_t count_roofs=u32(c,roof_count,write);if(count_roofs>STATE_ENTRIES)return false;if(!write){roof_count=count_roofs;state_roofs=calloc(roof_count?roof_count:1,sizeof(*state_roofs));if(!state_roofs)return false;}
    for(unsigned i=0;i<roof_count&&c->ok;i++){StateRoof* r=&state_roofs[i];text(c,r->map,sizeof(r->map),write);r->sector=u64(c,r->sector,write);r->index=u32(c,r->index,write);r->value=u32(c,r->value,write);if(!component(r->map)||r->index>=256)return false;}
    if(!write&&c->ok&&roof_count>1){qsort(state_roofs,roof_count,sizeof(*state_roofs),roof_compare);for(unsigned i=1;i<roof_count;i++)if(!roof_compare(&state_roofs[i-1],&state_roofs[i]))return false;}
    return c->ok;
}
bool rw_state_load(const char* slot){char path[RW_PATH_SIZE];rw_state_reset();if(!slot||!component(slot))return fail("Invalid loaded save slot");strcpy(state_slot,slot);if(!module_path(path,"Save/Current/renaissance-world.sav"))return false;if(!exists(path))return true;TigFile* file=tig_file_fopen(path,"rb");if(!file)return fail("Cannot read world update ledger");size_t length=tig_file_filelength(file);bool ok=checksum(file,false)&&tig_file_fseek(file,0,SEEK_SET)==0;Codec c={file,0,true};ok=ok&&state_codec(&c,false)&&c.bytes+32==length;tig_file_fclose(file);if(!ok){rw_state_reset();return fail("Malformed or unsupported world update ledger; save was not migrated");}return true;}
bool rw_state_save(void){char path[RW_PATH_SIZE];if(!module_path(path,"Save/Current/renaissance-world.sav"))return false;TigFile* file=tig_file_fopen(path,"w+b");if(!file)return fail("Cannot write world update ledger");Codec c={file,0,true};bool ok=state_codec(&c,true)&&c.bytes<=STATE_LIMIT-32&&checksum(file,true);if(tig_file_fclose(file)!=0)ok=false;if(!ok){tig_file_remove(path);return fail("World update ledger write failed; save publication aborted");}return true;}
static StatePackage* find_package(const char* id){for(unsigned i=0;i<state_count;i++)if(!strcmp(state_packages[i].id,id))return &state_packages[i];return NULL;}
static StateOp* find_op(StatePackage* p,const char* id){if(p)for(unsigned i=0;i<p->op_count;i++)if(!strcmp(p->ops[i].id,id))return &p->ops[i];return NULL;}
bool rw_state_validate_packages(void){
    for(unsigned i=0;i<state_count;i++){StatePackage* old=&state_packages[i];RwPackage* installed=NULL;for(unsigned j=0;j<rw_package_count;j++)if(!strcmp(old->id,rw_packages[j].id))installed=&rw_packages[j];if(!installed){rw_error("Required world update package is missing: %s",old->id);return false;}if(strcmp(old->module,installed->module)||installed->revision<old->revision||(installed->revision==old->revision&&memcmp(old->digest,installed->digest,32))){rw_error("Incompatible or changed package revision: %s",old->id);return false;}
        for(unsigned j=0;j<old->op_count;j++){bool found=false;for(unsigned k=0;k<installed->operation_count;k++)if(!strcmp(old->ops[j].id,installed->operations[k].id)&&!memcmp(old->ops[j].digest,installed->operations[k].digest,32))found=true;if(!found){rw_error("Published operation removed or changed: %s/%s",old->id,old->ops[j].id);return false;}}
        for(unsigned j=0;j<old->resource_count;j++){bool found=false;for(unsigned k=0;k<installed->resource_count;k++)if(!strcmp(old->resources[j].path,installed->resources[k].path)&&!memcmp(old->resources[j].digest,installed->resources[k].digest,32))found=true;if(!found){rw_error("Published resource removed or changed: %s/%s",old->id,old->resources[j].path);return false;}}
    }
    for(unsigned i=0;i<rw_package_count;i++){RwPackage* current=&rw_packages[i];StatePackage* p=find_package(current->id);if(!p){if(state_count>=RW_MAX_PACKAGES)return fail("Too many ledger packages");p=&state_packages[state_count++];strcpy(p->id,current->id);strcpy(p->module,current->module);}StateOp* ops=calloc(current->operation_count?current->operation_count:1,sizeof(*ops));RwResource* resources=calloc(current->resource_count?current->resource_count:1,sizeof(*resources));if(!ops||!resources){free(ops);free(resources);return fail("Cannot allocate world update ledger");}for(unsigned j=0;j<current->operation_count;j++){strcpy(ops[j].id,current->operations[j].id);memcpy(ops[j].digest,current->operations[j].digest,32);StateOp* old=find_op(p,ops[j].id);if(old)ops[j].outcome=old->outcome;}if(current->resource_count)memcpy(resources,current->resources,current->resource_count*sizeof(*resources));free(p->ops);free(p->resources);p->ops=ops;p->resources=resources;p->op_count=current->operation_count;p->resource_count=current->resource_count;p->previous_revision=p->revision;memcpy(p->previous_digest,p->digest,32);p->revision=current->revision;memcpy(p->digest,current->digest,32);}
    return true;
}
int rw_state_outcome(const RwPackage* package,const RwOperation* operation){StateOp* o=find_op(find_package(package->id),operation->id);return !o?RW_PENDING:memcmp(o->digest,operation->digest,32)?-1:(int)o->outcome;}
bool rw_state_record(const RwPackage* package,const RwOperation* operation,unsigned outcome,const char* detail){StateOp* o=find_op(find_package(package->id),operation->id);if(!o||memcmp(o->digest,operation->digest,32)||outcome>RW_FAILED)return fail("Invalid operation ledger record");if(o->outcome==RW_APPLIED&&outcome!=RW_APPLIED)return fail("Cannot replace a completed migration outcome");o->outcome=outcome;rw_log(package->id,operation->id,outcome==RW_APPLIED?"applied":outcome==RW_CONFLICT?"conflict":outcome==RW_FAILED?"failed":"pending",detail);return true;}
bool rw_state_roof_get(const char* map,uint64_t sector,unsigned index,uint32_t* value){for(unsigned i=0;i<roof_count;i++)if(state_roofs[i].sector==sector&&state_roofs[i].index==index&&!strcmp(state_roofs[i].map,map)){*value=state_roofs[i].value;return true;}return false;}
bool rw_state_roof_put(const char* map,uint64_t sector,unsigned index,uint32_t value){if(!component(map)||index>=256)return fail("Invalid persisted roof cell");for(unsigned i=0;i<roof_count;i++)if(state_roofs[i].sector==sector&&state_roofs[i].index==index&&!strcmp(state_roofs[i].map,map)){state_roofs[i].value=value;return true;}if(roof_count>=STATE_ENTRIES)return fail("Too many persisted roof cells");StateRoof* next=realloc(state_roofs,(roof_count+1)*sizeof(*next));if(!next)return fail("Cannot allocate persisted roof cells");state_roofs=next;StateRoof* r=&state_roofs[roof_count++];strcpy(r->map,map);r->sector=sector;r->index=index;r->value=value;return true;}
static void log_text(TigFile* stream,const char* s){if(!s)return;for(;*s;s++)tig_file_fputc((unsigned char)*s<32?' ':*s,stream);}
void rw_log(const char* package,const char* operation,const char* outcome,const char* detail){char dir[RW_PATH_SIZE],path[RW_PATH_SIZE];if(!module_path(dir,"Save/WorldUpdates")||!mkdirs(dir)||!path_join(path,dir,"updates.log"))return;TigFile* file=tig_file_fopen(path,"ab");if(!file)return;tig_file_fprintf(file,"%lld\t",(long long)time(NULL));const char* values[]={state_slot,package,operation,outcome,detail};for(unsigned i=0;i<5;i++){log_text(file,values[i]);tig_file_fputc(i==4?'\n':'\t',file);}tig_file_fclose(file);}

static const char* file_basename(const char* path){const char* name=path;for(const char* p=path;*p;p++)if(*p=='/'||*p=='\\')name=p+1;return name;}
static bool copy_slot(const char* slot,const char* directory){char pattern[RW_PATH_SIZE],source[RW_PATH_SIZE],target[RW_PATH_SIZE],tail[RW_PATH_SIZE];if(!component(slot))return fail("Invalid backup slot");snprintf(tail,sizeof(tail),"Save/%s*",slot);if(!module_path(pattern,tail)||!mkdirs(directory))return false;TigFileList files;tig_file_list_create(&files,pattern);tig_debug_printf("World update backup: pattern=%s count=%u directory=%s\n",pattern,files.count,directory);bool archive=false,index=false,metadata_found=false,ok=true;size_t prefix=strlen(slot);for(unsigned i=0;i<files.count;i++){const char* name=file_basename(files.entries[i].path);tig_debug_printf("World update backup entry: %s\n",name);const char* ext=strrchr(name,'.');if(!ext||strncmp(name,slot,prefix))continue;bool metadata=!strcmp(ext,".gsi");bool exact=!strcmp(name+prefix,".tfaf")||!strcmp(name+prefix,".tfai")||!strcmp(name+prefix,".bmp");if(!metadata&&!exact)continue;if(metadata)metadata_found=true;if(!strcmp(name+prefix,".tfaf"))archive=true;if(!strcmp(name+prefix,".tfai"))index=true;snprintf(tail,sizeof(tail),"Save/%s",name);if(strlen(name)+6>=sizeof(tail)||!module_path(source,tail)||!path_join(target,directory,name)||!copy(target,source)){ok=false;break;}}tig_file_list_destroy(&files);return ok&&archive&&index&&metadata_found;}
static bool backup_package(const RwPackage* p,const char* root){char folder[RW_PATH_SIZE],source[RW_PATH_SIZE],target[RW_PATH_SIZE],tail[96];snprintf(tail,sizeof(tail),"%s-%u",p->id,p->revision);if(!path_join(folder,root,tail)||!mkdirs(folder)||!path_join(source,p->directory,"runtime.rwp")||!path_join(target,folder,"runtime.rwp")||!copy(target,source))return false;for(unsigned j=0;j<p->resource_count;j++){if(!path_join(source,p->directory,p->resources[j].path)||!path_join(target,folder,p->resources[j].path))return false;char parent[RW_PATH_SIZE];strcpy(parent,target);char* slash=strrchr(parent,'/');if(slash){*slash=0;if(!mkdirs(parent))return false;}if(!copy(target,source))return false;}return true;}
bool rw_state_backup(const char* slot){if(backed_up)return true;bool pending=false;for(unsigned i=0;i<state_count;i++){StatePackage* p=&state_packages[i];if(p->previous_revision!=p->revision)pending=true;for(unsigned j=0;j<p->op_count;j++)if(p->ops[j].outcome==RW_PENDING||p->ops[j].outcome==RW_FAILED||p->ops[j].outcome==RW_CONFLICT)pending=true;}if(!pending){backed_up=true;return true;}if(!slot||!*slot){backed_up=true;rw_log("","","new-game","No pre-existing save slot to back up");return true;}if(strcmp(state_slot,slot))return fail("Backup slot differs from loaded save");char root[RW_PATH_SIZE],tail[128];if(!module_path(root,"Save/WorldUpdates")||!mkdirs(root))return fail("Cannot create update backup directory");do{snprintf(tail,sizeof(tail),"before-%s-%lld-%u",slot,(long long)time(NULL),++serial);if(!path_join(backup_directory,root,tail))return false;}while(exists(backup_directory));if(!copy_slot(slot,backup_directory))return fail("Cannot back up the complete loaded save; world update refused");
    for(unsigned i=0;i<rw_package_count;i++){RwPackage* p=&rw_packages[i];if(!backup_package(p,backup_directory))return fail("Cannot preserve update package/resources for rollback");StatePackage* state=find_package(p->id);if(state&&state->previous_revision&&state->previous_revision!=p->revision){char previous_dir[RW_PATH_SIZE];strcpy(previous_dir,p->directory);char* slash=strrchr(previous_dir,'/');if(!slash)return fail("Cannot locate previous immutable package revision");snprintf(slash+1,sizeof(previous_dir)-(size_t)(slash+1-previous_dir),"%u",state->previous_revision);RwPackage previous={0};if(!rw_package_read(previous_dir,&previous))return fail("Previous package revision is missing; keep it available for rollback");bool ok=!strcmp(previous.id,p->id)&&previous.revision==state->previous_revision&&!memcmp(previous.digest,state->previous_digest,32)&&backup_package(&previous,backup_directory);rw_package_free(&previous);if(!ok)return fail("Cannot preserve previous package revision for rollback");}}
    char provenance[RW_PATH_SIZE];if(!path_join(provenance,backup_directory,"README.txt"))return false;TigFile* info=tig_file_fopen(provenance,"wb");if(!info)return fail("Cannot write backup provenance");bool written=tig_file_fprintf(info,"Renaissance pre-update backup\nModule directory: %s\nLoaded slot: %s\nCreated: %lld\nRestore all slot files together and restore matching package revisions. Removing a package alone does not reverse saved effects.\n",state_directory,slot,(long long)time(NULL))>=0;if(tig_file_fclose(info)!=0)written=false;if(!written)return fail("Cannot write backup provenance");
    backed_up=true;rw_log("","","backup",backup_directory);return true;
}

/* Publication is recoverable, not a multi-file atomic rename. The old complete
 * slot is retained until a pending transaction has been removed successfully. */
typedef struct SaveTransaction {char directory[64],slot[64],metadata[RW_PATH_SIZE];uint32_t count;char files[64][RW_PATH_SIZE];} SaveTransaction;
static bool filename(const char* s){if(!s||!*s||!strcmp(s,".")||!strcmp(s,".."))return false;for(;*s;s++)if((unsigned char)*s<32||strchr("/\\:*?\"<>|",*s))return false;return true;}
static bool slot_file(const char* name,const char* slot){size_t n=strlen(slot),len=strlen(name);return filename(name)&&len>=n&&!strncmp(name,slot,n)&&(!strcmp(name+n,".tfaf")||!strcmp(name+n,".tfai")||!strcmp(name+n,".bmp")||(len>=4&&!strcmp(name+len-4,".gsi")));}
static bool transaction_codec(Codec* c,SaveTransaction* t,bool write){char magic[8]="RWTRANS";char got[8];memcpy(got,magic,8);io(c,got,8,write);text(c,t->directory,sizeof(t->directory),write);text(c,t->slot,sizeof(t->slot),write);text(c,t->metadata,sizeof(t->metadata),write);t->count=u32(c,t->count,write);if(memcmp(got,magic,8)||!component(t->directory)||!component(t->slot)||!slot_file(t->metadata,t->slot)||t->count>64)return false;for(unsigned i=0;i<t->count;i++){text(c,t->files[i],sizeof(t->files[i]),write);if(!slot_file(t->files[i],t->slot))return false;}return c->ok;}
static bool save_path(char out[RW_PATH_SIZE],const char* name){char root[RW_PATH_SIZE];return module_path(root,"Save")&&path_join(out,root,name);}
static bool transaction_path(char out[RW_PATH_SIZE],const SaveTransaction* t,const char* name){char root[RW_PATH_SIZE],dir[RW_PATH_SIZE];return module_path(root,"Save/WorldUpdates")&&path_join(dir,root,t->directory)&&path_join(out,dir,name);}
bool rw_save_recover(void){char pending[RW_PATH_SIZE];if(!module_path(pending,"Save/WorldUpdates/publish.pending"))return false;if(!exists(pending))return true;TigFile* stream=tig_file_fopen(pending,"rb");if(!stream)return fail("Cannot read interrupted save transaction");SaveTransaction t={0};Codec c={stream,0,true};bool valid=transaction_codec(&c,&t,false)&&tig_file_fgetc(stream)==EOF;tig_file_fclose(stream);if(!valid)return fail("Invalid save recovery journal; existing backup retained");
    char source[RW_PATH_SIZE],target[RW_PATH_SIZE],name[128];
    /* Check all backup files before touching the incomplete destination. */
    for(unsigned i=0;i<t.count;i++)if(!transaction_path(source,&t,t.files[i])||!exists(source))return fail("Save recovery backup is incomplete; refusing to guess");
    if(!save_path(target,t.metadata))return false;if(exists(target)&&tig_file_remove(target)!=0)return fail("Cannot hide incomplete save metadata");
    for(unsigned i=0;i<t.count;i++){size_t n=strlen(t.files[i]);if(n>=4&&!strcmp(t.files[i]+n-4,".gsi")){if(!save_path(target,t.files[i]))return false;if(exists(target)&&tig_file_remove(target)!=0)return fail("Cannot restore saved metadata");}}
    const char* extensions[]={".tfaf",".tfai",".bmp"};for(unsigned i=0;i<3;i++){snprintf(name,sizeof(name),"%s%s",t.slot,extensions[i]);if(!save_path(target,name))return false;bool had=false;for(unsigned j=0;j<t.count;j++)if(!strcmp(name,t.files[j]))had=true;if(!had&&exists(target)&&tig_file_remove(target)!=0)return fail("Cannot remove incomplete new save file");}
    for(unsigned pass=0;pass<2;pass++)for(unsigned i=0;i<t.count;i++){size_t n=strlen(t.files[i]);bool meta=n>=4&&!strcmp(t.files[i]+n-4,".gsi");if(meta!=(pass==1))continue;if(!transaction_path(source,&t,t.files[i])||!save_path(target,t.files[i])||!copy(target,source))return fail("Could not restore previous save; recovery journal retained");}
    if(tig_file_remove(pending)!=0)return fail("Previous save restored but recovery journal could not be cleared");rw_log("","","save-recovered",t.slot);return true;
}
bool rw_save_stage(char stage[9]){if(!rw_save_recover())return false;for(unsigned i=0;i<100000;i++){snprintf(stage,9,"RWS%05X",((unsigned)time(NULL)+ ++serial)&0xfffff);char name[32],pattern[RW_PATH_SIZE];snprintf(name,sizeof(name),"%s*",stage);if(!save_path(pattern,name))return false;TigFileList list;tig_file_list_create(&list,pattern);bool empty=list.count==0;tig_file_list_destroy(&list);if(empty)return true;}return fail("Cannot allocate temporary save slot");}
void rw_save_discard(const char* stage){if(!component(stage))return;char name[80],pattern[RW_PATH_SIZE],path[RW_PATH_SIZE];snprintf(name,sizeof(name),"%s*",stage);if(!save_path(pattern,name))return;TigFileList list;tig_file_list_create(&list,pattern);for(unsigned i=0;i<list.count;i++)if(slot_file(file_basename(list.entries[i].path),stage)&&save_path(path,file_basename(list.entries[i].path)))tig_file_remove(path);tig_file_list_destroy(&list);}
bool rw_save_publish(const char* stage,const char* slot,const char* description){if(!component(stage)||!component(slot)||!description||(*description&&!filename(description)))return fail("Invalid save publication name");SaveTransaction t={0};strcpy(t.slot,slot);if(snprintf(t.metadata,sizeof(t.metadata),"%s%s.gsi",slot,description)>=sizeof(t.metadata))return fail("Save description is too long");char root[RW_PATH_SIZE],dir[RW_PATH_SIZE],pending[RW_PATH_SIZE],temp[RW_PATH_SIZE],source[RW_PATH_SIZE],target[RW_PATH_SIZE],name[RW_PATH_SIZE];if(!module_path(root,"Save/WorldUpdates")||!mkdirs(root))return fail("Cannot create save recovery directory");do{snprintf(t.directory,sizeof(t.directory),"save-%lld-%u",(long long)time(NULL),++serial);if(!path_join(dir,root,t.directory))return false;}while(exists(dir));if(!mkdirs(dir))return fail("Cannot create save transaction backup");snprintf(name,sizeof(name),"%s*",slot);if(!save_path(source,name))return false;TigFileList list;tig_file_list_create(&list,source);bool ok=true;for(unsigned i=0;i<list.count;i++)if(slot_file(file_basename(list.entries[i].path),slot)){if(t.count>=64){ok=false;break;}strcpy(t.files[t.count++],file_basename(list.entries[i].path));if(!save_path(source,file_basename(list.entries[i].path))||!path_join(target,dir,file_basename(list.entries[i].path))||!copy(target,source)){ok=false;break;}}tig_file_list_destroy(&list);if(!ok)return fail("Cannot preserve existing save before publication");
    if(!path_join(pending,root,"publish.pending")||!path_join(temp,root,"publish.tmp"))return false;if(exists(pending))return fail("An unresolved save transaction already exists");TigFile* file=tig_file_fopen(temp,"wb");if(!file)return fail("Cannot write save transaction journal");Codec c={file,0,true};ok=transaction_codec(&c,&t,true);if(tig_file_fclose(file)!=0)ok=false;if(!ok||tig_file_rename(temp,pending)!=0)return fail("Cannot publish save recovery journal");
    for(unsigned i=0;i<t.count&&ok;i++){size_t n=strlen(t.files[i]);if(n>=4&&!strcmp(t.files[i]+n-4,".gsi")){ok=save_path(target,t.files[i]);if(ok&&exists(target))ok=tig_file_remove(target)==0;}}
    const char* extensions[]={".tfaf",".tfai",".bmp"};for(unsigned i=0;i<3&&ok;i++){snprintf(name,sizeof(name),"%s%s",stage,extensions[i]);ok=save_path(source,name);snprintf(name,sizeof(name),"%s%s",slot,extensions[i]);ok=ok&&save_path(target,name)&&copy(target,source);}
    if(ok){snprintf(name,sizeof(name),"%s%s.gsi",stage,description);ok=save_path(source,name)&&save_path(target,t.metadata)&&copy(target,source);}if(ok)ok=tig_file_remove(pending)==0;if(!ok){bool restored=rw_save_recover();rw_save_discard(stage);return fail(restored?"Save publication failed; previous complete slot restored":"Save publication failed; recovery pending, backup retained");}rw_save_discard(stage);for(unsigned i=0;i<t.count;i++)if(path_join(target,dir,t.files[i]))tig_file_remove(target);tig_file_rmdir(dir);rw_log("","","save-published",slot);return true;
}
